{"tool":"newFileCreated","path":"src/main/kotlin/set/starlev/render/KickGui.kt","content":"package set.starlev.render

import net.minecraft.client.Minecraft
import net.minecraft.client.gui.GuiGraphics
import net.minecraft.client.gui.components.Button
import net.minecraft.client.gui.screens.Screen
import net.minecraft.network.chat.Component

class KickGui(private val moderator: String, private val reason: String) : Screen(Component.literal("§c§lВЫ БЫЛИ КИКНУТЫ")) {
    private var scrollOffset = 0.0
    private var isDragging = false
    private var lastMouseY = 0.0

    companion object {
        fun showKickScreen(mod: String, reason: String) {
            Minecraft.getInstance().setScreen(KickGui(mod, reason))
        }
    }

    override fun init() {
        val centerX = width / 2
        val buttonY = height / 2 + 80

        addRenderableWidget(
            Button.builder(Component.literal("§c§lВЫЙТИ В ГЛАВНОЕ МЕНЮ")) {
                Minecraft.getInstance().level?.disconnect()
                Minecraft.getInstance().setScreen(null)
            }.bounds(centerX - 100, buttonY, 200, 20).build()
        )
    }

    override fun renderBackground(graphics: GuiGraphics, mouseX: Int, mouseY: Int, delta: Float) {
        graphics.fill(0, 0, width, height, 0xD0200000.toInt())
    }

    override fun render(graphics: GuiGraphics, mouseX: Int, mouseY: Int, delta: Float) {
        renderBackground(graphics, mouseX, mouseY, delta)

        val centerX = width / 2
        val centerY = height / 2

        // Заголовок
        graphics.drawCenteredString(font, "§c§l✖ ВАС КИКНУЛИ ИЗ ПАТИ ✖", centerX, 30, 0xFF5555)

        // Разделитель
        graphics.fill(centerX - 150, 50, centerX + 150, 51, 0xFF555555.toInt())

        // Модератор
        graphics.drawCenteredString(font, "§7Модератор:", centerX, 65, 0xAAAAAA)
        graphics.drawCenteredString(font, "§e$moderator", centerX, 78, 0xFFFF55)

        // Причина (с прокруткой если длинная)
        graphics.drawCenteredString(font, "§7Причина:", centerX, 100, 0xAAAAAA)

        val reasonBoxTop = 115
        val reasonBoxBottom = height / 2 + 50
        val reasonBoxLeft = centerX - 150
        val reasonBoxRight = centerX + 150

        // Фон окна причины
        graphics.fill(reasonBoxLeft, reasonBoxTop, reasonBoxRight, reasonBoxBottom, 0x80000000.toInt())
        graphics.fill(reasonBoxLeft, reasonBoxTop, reasonBoxRight, reasonBoxTop + 1, 0xFF555555.toInt())
        graphics.fill(reasonBoxLeft, reasonBoxBottom - 1, reasonBoxRight, reasonBoxBottom, 0xFF555555.toInt())

        // Рендерим текст причины с прокруткой
        val wrappedLines = wrapText(reason, reasonBoxRight - reasonBoxLeft - 20)
        val lineHeight = font.lineHeight + 2
        val totalHeight = wrappedLines.size * lineHeight
        val maxScroll = maxOf(0.0, (totalHeight - (reasonBoxBottom - reasonBoxTop - 10)).toDouble())
        scrollOffset = scrollOffset.coerceIn(0.0, maxScroll)

        graphics.enableScissor(reasonBoxLeft + 5, reasonBoxTop + 5, reasonBoxRight - 5, reasonBoxBottom - 5)
        for ((i, line) in wrappedLines.withIndex()) {
            val y = reasonBoxTop + 8 + (i * lineHeight) - scrollOffset.toInt()
            if (y >= reasonBoxTop && y <= reasonBoxBottom - lineHeight) {
                graphics.drawString(font, "§f$line", reasonBoxLeft + 10, y, 0xFFFFFF)
            }
        }
        graphics.disableScissor()

        // Полоса прокрутки
        if (maxScroll > 0) {
            val scrollBarHeight = ((reasonBoxBottom - reasonBoxTop - 10).toDouble() / totalHeight * (reasonBoxBottom - reasonBoxTop - 10)).toInt().coerceAtLeast(10)
            val scrollBarY = reasonBoxTop + 5 + (scrollOffset / maxScroll * (reasonBoxBottom - reasonBoxTop - 10 - scrollBarHeight)).toInt()
            graphics.fill(reasonBoxRight - 8, scrollBarY, reasonBoxRight - 4, scrollBarY + scrollBarHeight, 0xFF888888.toInt())
        }

        super.render(graphics, mouseX, mouseY, delta)
    }

    private fun wrapText(text: String, maxWidth: Int): List<String> {
        val words = text.split(" ")
        val lines = mutableListOf<String>()
        var currentLine = ""

        for (word in words) {
            val testLine = if (currentLine.isEmpty()) word else "$currentLine $word"
            if (font.width(testLine) > maxWidth && currentLine.isNotEmpty()) {
                lines.add(currentLine)
                currentLine = word
            } else {
                currentLine = testLine
            }
        }
        if (currentLine.isNotEmpty()) lines.add(currentLine)
        return lines
    }

    override fun mouseScrolled(mouseX: Double, mouseY: Double, scrollX: Double, scrollY: Double): Boolean {
        scrollOffset -= scrollY * 12.0
        return true
    }

    override fun mouseDragged(mouseX: Double, mouseY: Double, button: Int, dragX: Double, dragY: Double): Boolean {
        if (button == 0 && isDragging) {
            scrollOffset -= dragY
            lastMouseY = mouseY
            return true
        }
        return super.mouseDragged(mouseX, mouseY, button, dragX, dragY)
    }

    override fun mousePressed(mouseX: Double, mouseY: Double, button: Int): Boolean {
        if (button == 0) {
            isDragging = true
            lastMouseY = mouseY
        }
        return super.mousePressed(mouseX, mouseY, button)
    }

    override fun mouseReleased(mouseX: Double, mouseY: Double, button: Int): Boolean {
        if (button == 0) {
            isDragging = false
        }
        return super.mouseReleased(mouseX, mouseY, button)
    }

    override fun isPauseScreen(): Boolean = false
