{"tool":"newFileCreated","path":"src/main/kotlin/set/starlev/features/combat/dungeons/solvers/ThreeWeirdosChest.kt","content":"package set.starlev.features.combat.dungeons.solvers

import net.minecraft.client.Minecraft
import net.minecraft.core.BlockPos
import net.minecraft.world.level.block.Blocks
import net.minecraft.world.phys.AABB
import set.starlev.StarredHeltix
import set.starlev.render.RenderEvents
import set.starlev.utils.detectors.DungeonDetector
import set.starlev.utils.detectors.MobHeadDisplayDetector

/**
 * Подсветка сундука Трёх незнакомцев.
 * Находит TextDisplay с ником правильного незнакомца и подсвечивает его сундук.
 * Сундук находится левее НПС на 1 блок и ближе к игроку на 1 блок.
 */
object ThreeWeirdosChest {
    private val mc = Minecraft.getInstance()
    private var correctStrangerName: String? = null
    private var correctStrangerPos: BlockPos? = null
    private var lastChestPos: BlockPos? = null

    fun init() {
        RenderEvents.register { context ->
            if (!StarredHeltix.feature.dungeons.solvers.threeWeirdos) {
                lastChestPos = null
                return@register
            }
            if (!DungeonDetector.isInDungeon()) {
                lastChestPos = null
                return@register
            }

            val player = mc.player ?: return@register
            val level = mc.level ?: return@register

            // Ищем TextDisplay с именем правильного незнакомца
            if (correctStrangerName == null) {
                // Пытаемся получить имя из ThreeWeirdos
                correctStrangerName = ThreeWeirdos.getCorrectStranger()
            }

            if (correctStrangerName == null) {
                lastChestPos = null
                return@register
            }

            // Ищем НПС (TextDisplay) с именем незнакомца
            for (entity in level.entitiesForRendering()) {
                val displays = MobHeadDisplayDetector.getHeadDisplays(entity)
                for (comp in displays.textDisplays) {
                    val text = comp.string.replace(Regex("(?i)§[0-9a-fk-orlnmxz]"), "").trim()
                    if (text.equals(correctStrangerName, ignoreCase = true)) {
                        correctStrangerPos = entity.blockPosition()
                        break
                    }
                }
            }

            if (correctStrangerPos == null) {
                lastChestPos = null
                return@register
            }

            // Вычисляем позицию сундука: левее на 1 блок и ближе к игроку на 1 блок
            val npcPos = correctStrangerPos!!
            val playerPos = player.blockPosition()

            // Направление от НПС к игроку
            val dx = playerPos.x - npcPos.x
            val dz = playerPos.z - npcPos.z

            // Сундук левее (перпендикулярно направлению к игроку) и ближе к игроку
            // "Левее" = поворот на 90 градусов против часовой стрелки
            val leftX = -dz
            val leftZ = dx

            val chestPos = BlockPos(
                npcPos.x + leftX.coerceIn(-1, 1),
                npcPos.y,
                npcPos.z + leftZ.coerceIn(-1, 1)
            )

            // Проверяем, что там действительно сундук
            val blockState = level.getBlockState(chestPos)
            if (blockState.`is`(Blocks.CHEST) || blockState.`is`(Blocks.TRAPPED_CHEST)) {
                lastChestPos = chestPos

                // Подсветка сундука
                val chestBox = AABB(chestPos)
                context.renderBox(chestBox, 0f, 1f, 0f, 0.3f, fill = true)
                context.renderBox(chestBox, 0f, 1f, 0f, 1.0f, fill = false)
                context.renderBoxThroughBlocks(chestBox.inflate(0.01), 0f, 1f, 0f, 1.0f, fill = false, thickness = 3f)

                // Текст над сундуком
                context.renderText(
                    "§a§lСУНДУК: $correctStrangerName",
                    chestPos.x + 0.5,
                    chestPos.y + 1.5,
                    chestPos.z + 0.5,
                    scale = 1.2f,
                    color = 0xFF00FF00.toInt(),
                    seeThrough = true
                )
            } else {
                // Если сундук не найден по расчётной позиции, ищем рядом
                val searchBox = AABB(npcPos).inflate(3.0)
                for (x in chestPos.x - 2..chestPos.x + 2) {
                    for (y in chestPos.y - 1..chestPos.y + 1) {
                        for (z in chestPos.z - 2..chestPos.z + 2) {
                            val pos = BlockPos(x, y, z)
                            val state = level.getBlockState(pos)
                            if (state.`is`(Blocks.CHEST) || state.`is`(Blocks.TRAPPED_CHEST)) {
                                lastChestPos = pos
                                val box = AABB(pos)
                                context.renderBox(box, 0f, 1f, 0f, 0.3f, fill = true)
                                context.renderBox(box, 0f, 1f, 0f, 1.0f, fill = false)
                                context.renderText(
                                    "§a§lСУНДУК: $correctStrangerName",
                                    pos.x + 0.5,
                                    pos.y + 1.5,
                                    pos.z + 0.5,
                                    scale = 1.2f,
                                    color = 0xFF00FF00.toInt(),
                                    seeThrough = true
                                )
                                break@searchBox
                            }
                        }
                    }
                }
            }
        }
    }

    fun reset() {
        correctStrangerName = null
        correctStrangerPos = null
        lastChestPos = null
    }
