{"tool":"newFileCreated","path":"src/main/kotlin/set/starlev/utils/RegexCache.kt","content":"package set.starlev.utils

import set.starlev.StarredHeltix
import java.util.regex.Pattern

/**
 * Кэш скомпилированных Regex для ускорения обработки текста.
 * Избегает повторной компиляции одних и тех же паттернов.
 */
object RegexCache {
    private val cache = mutableMapOf<String, Pattern>()

    /**
     * Получает скомпилированный Pattern из кэша или компилирует новый.
     * Если кэш отключён в конфиге, компилирует каждый раз.
     */
    fun get(pattern: String, flags: Int = 0): Pattern {
        val config = try {
            StarredHeltix.feature.optimization.renderOptimizations.regexCache
        } catch (_: Throwable) {
            true
        }

        if (!config) {
            return Pattern.compile(pattern, flags)
        }

        val key = if (flags == 0) pattern else "$pattern|$flags"
        return cache.getOrPut(key) {
            Pattern.compile(pattern, flags)
        }
    }

    /**
     * Быстрая замена с использованием кэшированного Pattern.
     */
    fun replace(input: String, pattern: String, replacement: String, flags: Int = 0): String {
        return get(pattern, flags).matcher(input).replaceAll(replacement)
    }

    /**
     * Быстрая проверка совпадения с использованием кэшированного Pattern.
     */
    fun matches(input: String, pattern: String, flags: Int = 0): Boolean {
        return get(pattern, flags).matcher(input).find()
    }

    /**
     * Очистка кэша (например, при смене конфига).
     */
    fun clear() {
        cache.clear()
    }

    /**
     * Размер кэша (для отладки).
     */
    fun size(): Int = cache.size
}
